// Fixtures generated by testdata/gen-messages.ts from the Node SDK builders.
func TestSignedMessageFixturesMatchNode(t *testing.T) {
	raw, err := os.ReadFile("testdata/messages.json")
	if err != nil {
		t.Fatal(err)
	}
	var fx struct {
		Attestation []struct {
			In struct {
				Wallet, Nonce, AttestationText string
				AttestationVersion             int
				NodePubkey                     *string
			} `json:"in"`
			Out string `json:"out"`
		} `json:"attestation"`
		PayoutWallet []struct {
			In  struct{ UserID, Wallet, Address, Chain, Nonce string } `json:"in"`
			Out string                                                 `json:"out"`
		} `json:"payoutWallet"`
		Withdraw []struct {
			In  struct{ UserID, Wallet, AmountMusd, IdempotencyKey, Nonce string } `json:"in"`
			Out string                                                             `json:"out"`
		} `json:"withdraw"`
	}
	if err := json.Unmarshal(raw, &fx); err != nil {
		t.Fatal(err)
	}
	if len(fx.Attestation) < 2 || len(fx.PayoutWallet) < 1 || len(fx.Withdraw) < 1 {
		t.Fatal("fixtures missing")
	}
	for _, a := range fx.Attestation {
		pk := ""
		if a.In.NodePubkey != nil {
			pk = *a.In.NodePubkey
		}
		got := BuildAttestationMessage(AttestationParams{a.In.Wallet, a.In.Nonce, a.In.AttestationVersion, a.In.AttestationText, pk})
		if got != a.Out {
			t.Fatalf("attestation:\n%q\nwant\n%q", got, a.Out)
		}
	}
	for _, p := range fx.PayoutWallet {
		if got := BuildPayoutWalletMessage(p.In.UserID, p.In.Wallet, p.In.Address, p.In.Chain, p.In.Nonce); got != p.Out {
			t.Fatalf("payout:\n%q\nwant\n%q", got, p.Out)
		}
	}
	for _, w := range fx.Withdraw {
		if got := BuildWithdrawMessage(w.In.UserID, w.In.Wallet, w.In.AmountMusd, w.In.IdempotencyKey, w.In.Nonce); got != w.Out {
			t.Fatalf("withdraw:\n%q\nwant\n%q", got, w.Out)
		}
	}
}

// ---- node register

func nodeChallengeJSON(signerAddr, pubkey string, mutate func(string) string) string {
	nonce := strings.Repeat("d", 64)
	msg := BuildAttestationMessage(AttestationParams{signerAddr, nonce, 2, "terms v2", pubkey})
	if mutate != nil {
		msg = mutate(msg)
	}
	b, _ := json.Marshal(map[string]any{
		"nonce": nonce, "attestationText": "terms v2", "attestationVersion": 2, "policyVersion": 5,
		"message": msg, "expiresAt": "t",
		"powChallenge": map[string]any{"challengeId": testUUID, "prefix": "pfx:", "difficulty": 8, "algorithm": "sha256", "expiresAt": "t"},
	})
	return string(b)
}

func TestNodeRegisterFlow(t *testing.T) {
	c, rt := newTestClient(t)
	s := &fakeSigner{addr: testAddr}
	pk := strings.Repeat("0f", 32)
	nodeKey := "dn_node_" + strings.Repeat("e", 64)
	rt.push(ok(nodeChallengeJSON(testAddr, pk, nil)),
		ok(`{"nodeId":"`+testUUID+`","nodeKey":"`+nodeKey+`","status":"pending","attestationVersion":2}`))
	n, err := c.Nodes.Register(context.Background(), RegisterNodeOptions{Signer: s, NodePubkey: strings.ToUpper(pk), MaxStreams: Int(8), MaxGbDay: Int(50)})
	if err != nil {
		t.Fatal(err)
	}
	if n.NodeKey.Reveal() != nodeKey || n.NodeID != testUUID || len(s.calls) != 1 {
		t.Fatalf("%+v calls=%d", n, len(s.calls))
	}
	jsonEq(t, rt.reqs[0].Body, `{"nodePubkey":"`+pk+`"}`)
	var body struct {
		Nonce, WalletSignature, NodePubkey string
		AttestationVersion, MaxStreams     int
		MaxGbDay                           int
		Pow                                struct{ ChallengeID, Nonce string }
	}
	_ = json.Unmarshal([]byte(rt.reqs[1].Body), &body)
	if rt.reqs[1].Path != "/v1/nodes" || body.WalletSignature != testSig || body.NodePubkey != pk || body.MaxStreams != 8 || body.MaxGbDay != 50 || body.Pow.ChallengeID != testUUID {
		t.Fatalf("register body %s", rt.reqs[1].Body)
	}
	h := sha256.Sum256([]byte("pfx:" + body.Pow.Nonce))
	if leadingZeroBits(h[:]) < 8 {
		t.Fatal("PoW solution does not verify")
	}
	if rt.reqs[1].Header.Get("Authorization") != "Bearer "+testKey {
		t.Fatal("register must use the API key")
	}
}

func TestNodeRegisterRefusals(t *testing.T) {
	ctx := context.Background()
	nodeKey := "dn_node_" + strings.Repeat("e", 64)
	cases := map[string]struct {
		chal  string
		reg   string
		check func(error) bool
	}{
		"message mismatch": {chal: nodeChallengeJSON(testAddr, "", func(m string) string { return strings.Replace(m, "terms v2", "terms v3", 1) }), check: isType[*ProtocolError]},
		"wrong wallet":     {chal: nodeChallengeJSON("0x"+strings.Repeat("9", 40), "", nil), check: isType[*ProtocolError]},
		"bad nonce":        {chal: strings.Replace(nodeChallengeJSON(testAddr, "", nil), strings.Repeat("d", 64), "zz", 1), check: isType[*ProtocolError]},
		"bad node key":     {chal: nodeChallengeJSON(testAddr, "", nil), reg: `{"nodeId":"` + testUUID + `","nodeKey":"dn_node_short"}`, check: isType[*ProtocolError]},
		"bad node id":      {chal: nodeChallengeJSON(testAddr, "", nil), reg: `{"nodeId":"x","nodeKey":"` + nodeKey + `"}`, check: isType[*ProtocolError]},
	}
	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			c, rt := newTestClient(t)
			s := &fakeSigner{addr: testAddr}
			rt.push(ok(tc.chal))
			if tc.reg != "" {
				rt.push(ok(tc.reg))
			}
			_, err := c.Nodes.Register(ctx, RegisterNodeOptions{Signer: s})
			if !tc.check(err) {
				t.Fatalf("got %v", err)
			}
			if tc.reg == "" && len(s.calls) != 0 {
				t.Fatal("signer was called")
			}
		})
	}
}

func TestNodeRegisterPowLimits(t *testing.T) {
	if _, err := SolvePow("p", 33, 10); !isType[*ProtocolError](err) {
		t.Fatal("difficulty 33")
	}
	if _, err := SolvePow("", 1, 10); !isType[*ProtocolError](err) {
		t.Fatal("empty prefix")
	}
	if _, err := SolvePow(strings.Repeat("p", 257), 1, 10); !isType[*ProtocolError](err) {
		t.Fatal("long prefix")
	}
	if _, err := SolvePow("p", 32, 5); !isType[*ProtocolError](err) {
		t.Fatal("iteration cap")
	}
}

// ---- withdraw

func withdrawChallenge(signer, amount, key string, mutate func(string) string) string {
	nonce := strings.Repeat("c", 64)
	msg := BuildWithdrawMessage(testUUID, signer, amount, key, nonce)
	if mutate != nil {
		msg = mutate(msg)
	}
	b, _ := json.Marshal(map[string]any{"nonce": nonce, "message": msg, "expiresAt": "t", "signer": strings.ToLower(signer)})
	return string(b)
}

func TestWithdrawFlow(t *testing.T) {
	c, rt := newTestClient(t)
	s := &fakeSigner{addr: testAddr}
	rt.push(ok(withdrawChallenge(testAddr, "2500000", "dn-key_12345678", nil)),
		ok(`{"payout":{"id":"p1","amount":{"musd":"2500000","usd":"2.500000"},"trigger":"on_demand","status":"pending","txHash":null,"createdAt":"t"},"duplicate":false}`))
	r, err := c.Credits.Withdraw(context.Background(), WithdrawOptions{AmountMusd: "2500000", Signer: s, IdempotencyKey: "dn-key_12345678"})
	if err != nil {
		t.Fatal(err)
	}
	if r.IdempotencyKey != "dn-key_12345678" || r.Payout.Status != "pending" || len(s.calls) != 1 {
		t.Fatalf("%+v", r)
	}
	jsonEq(t, rt.reqs[0].Body, `{"amountMusd":"2500000","idempotencyKey":"dn-key_12345678"}`)
	jsonEq(t, rt.reqs[1].Body, `{"amountMusd":"2500000","idempotencyKey":"dn-key_12345678","nonce":"`+strings.Repeat("c", 64)+`","signature":"`+testSig+`"}`)
	if rt.reqs[0].Path != "/v1/credits/withdraw/challenge" || rt.reqs[1].Path != "/v1/credits/withdraw" {
		t.Fatal("paths")
	}
}

func TestWithdrawRefusals(t *testing.T) {
	key := "dn-key_12345678"
	cases := map[string]string{
		"mismatch":      withdrawChallenge(testAddr, "2500000", key, func(m string) string { return strings.Replace(m, "2500000", "9500000", 1) }),
		"server signer": strings.Replace(withdrawChallenge(testAddr, "2500000", key, nil), `"signer":"`+strings.ToLower(testAddr), `"signer":"0x`+strings.Repeat("1", 40), 1),
		"user not uuid": withdrawChallenge(testAddr, "2500000", key, func(m string) string { return strings.Replace(m, testUUID, "admin", 1) }),
		"trailing line": withdrawChallenge(testAddr, "2500000", key, func(m string) string { return m + "\n" }),
		"bad nonce":     strings.Replace(withdrawChallenge(testAddr, "2500000", key, nil), `"nonce":"`+strings.Repeat("c", 64), `"nonce":"x`, 1),
	}
	for name, chal := range cases {
		t.Run(name, func(t *testing.T) {
			c, rt := newTestClient(t)
			s := &fakeSigner{addr: testAddr}
			rt.push(ok(chal))
			_, err := c.Credits.Withdraw(context.Background(), WithdrawOptions{AmountMusd: 2_500_000, Signer: s, IdempotencyKey: key})
			if !isType[*ProtocolError](err) || len(s.calls) != 0 || len(rt.reqs) != 1 {
				t.Fatalf("err=%v calls=%d reqs=%d", err, len(s.calls), len(rt.reqs))
			}
		})
	}
}

func TestBadSignatureFromSigner(t *testing.T) {
	for name, s := range map[string]*fakeSigner{
		"short":  {addr: testAddr, sig: "0x" + strings.Repeat("a", 129)},
		"long":   {addr: testAddr, sig: "0x" + strings.Repeat("a", 201)},
		"nonhex": {addr: testAddr, sig: "0x" + strings.Repeat("z", 130)},
		"error":  {addr: testAddr, err: errors.New("hsm offline " + testKey)},
	} {
		t.Run(name, func(t *testing.T) {
			c, rt := newTestClient(t)
			rt.push(ok(withdrawChallenge(testAddr, "1000000", "dn-key_12345678", nil)))
			_, err := c.Credits.Withdraw(context.Background(), WithdrawOptions{AmountMusd: 1_000_000, Signer: s, IdempotencyKey: "dn-key_12345678"})
			if !isType[*ProtocolError](err) || len(rt.reqs) != 1 || strings.Contains(err.Error(), testKey) {
				t.Fatalf("err=%v reqs=%d", err, len(rt.reqs))
			}
		})
	}
}

// ---- convert

func convertChallenge(signer, amount, key string, mutate func(string) string) string {
	nonce := strings.Repeat("d", 64)
	msg := BuildConvertMessage(testUUID, signer, amount, key, nonce)
	if mutate != nil {
		msg = mutate(msg)
	}
	b, _ := json.Marshal(map[string]any{"nonce": nonce, "message": msg, "expiresAt": "t", "signer": strings.ToLower(signer)})
	return string(b)
}

func TestConvertMessageMatchesServer(t *testing.T) {
	want := "DominusNode credit conversion\nAction: convert\nUser: " + testUUID + "\nAccount wallet: " + strings.ToLower(testAddr) +
		"\nAmount (µUSD): 10000\nIdempotency key: dn-key_12345678\nNonce: " + strings.Repeat("d", 64)
	if got := BuildConvertMessage(testUUID, testAddr, "10000", "dn-key_12345678", strings.Repeat("d", 64)); got != want {
		t.Fatalf("got %q", got)
	}
}

func TestConvertFlow(t *testing.T) {
	c, rt := newTestClient(t)
	s := &fakeSigner{addr: testAddr}
	key := "dn-key_12345678"
	rt.push(ok(convertChallenge(testAddr, "10000", key, nil)),
		ok(`{"converted":{"musd":"10000","usd":"0.010000"},"convertedCents":1,"duplicate":false}`))
	r, err := c.Credits.Convert(context.Background(), ConvertOptions{AmountMusd: int64(10_000), Signer: s, IdempotencyKey: key})
	if err != nil {
		t.Fatal(err)
	}
	if r.IdempotencyKey != key || r.Converted.Musd != "10000" || r.ConvertedCents != 1 || len(s.calls) != 1 {
		t.Fatalf("%+v", r)
	}
	if rt.reqs[0].Path != "/v1/credits/convert/challenge" || rt.reqs[1].Path != "/v1/credits/convert" {
		t.Fatal("paths")
	}
	jsonEq(t, rt.reqs[0].Body, `{"amountMusd":"10000"}`)
	jsonEq(t, rt.reqs[1].Body, `{"amountMusd":"10000","nonce":"`+strings.Repeat("d", 64)+`","signature":"`+testSig+`"}`)
	for _, q := range rt.reqs {
		if q.Header.Get("Idempotency-Key") != key || q.Method != "POST" {
			t.Fatal("idempotency header / method")
		}
	}
}

func TestConvertRefusals(t *testing.T) {
	key := "dn-key_12345678"
	cases := map[string]string{
		"text mismatch": convertChallenge(testAddr, "10000", key, func(m string) string { return strings.Replace(m, "10000", "99999", 1) }),
		"action swap":   convertChallenge(testAddr, "10000", key, func(m string) string { return strings.Replace(m, "Action: convert", "Action: withdraw", 1) }),
		"server signer": strings.Replace(convertChallenge(testAddr, "10000", key, nil), `"signer":"`+strings.ToLower(testAddr), `"signer":"0x`+strings.Repeat("1", 40), 1),
		"bad nonce":     strings.Replace(convertChallenge(testAddr, "10000", key, nil), `"nonce":"`+strings.Repeat("d", 64), `"nonce":"x`, 1),
	}
	for name, chal := range cases {
		t.Run(name, func(t *testing.T) {
			c, rt := newTestClient(t)
			s := &fakeSigner{addr: testAddr}
			rt.push(ok(chal))
			_, err := c.Credits.Convert(context.Background(), ConvertOptions{AmountMusd: 10_000, Signer: s, IdempotencyKey: key})
			if !isType[*ProtocolError](err) || len(s.calls) != 0 || len(rt.reqs) != 1 {
				t.Fatalf("err=%v calls=%d reqs=%d", err, len(s.calls), len(rt.reqs))
			}
		})
	}
}

func TestConvertMissingSigner(t *testing.T) {
	c, rt := newTestClient(t)
	_, err := c.Credits.Convert(context.Background(), ConvertOptions{AmountMusd: 10_000})
	if err == nil || len(rt.reqs) != 0 {
		t.Fatalf("err=%v reqs=%d", err, len(rt.reqs))
	}
}

func TestConvertDefaultIdempotencyKey(t *testing.T) {
	c, rt := newTestClient(t)
	s := &fakeSigner{addr: testAddr}
	// Server text built for another key: the SDK must refuse before signing.
	rt.push(ok(convertChallenge(testAddr, "10000", "dn-other_123456", nil)))
	_, err := c.Credits.Convert(context.Background(), ConvertOptions{AmountMusd: "10000", Signer: s})
	if !isType[*ProtocolError](err) || len(s.calls) != 0 {
		t.Fatalf("err=%v", err)
	}
	k := rt.last(t).Header.Get("Idempotency-Key")
	if !strings.HasPrefix(k, "dn-") || len(k) != 39 || !idempotencyKeyRE.MatchString(k) {
		t.Fatalf("key %q", k)
	}
}

// ---- payout wallet

const newPayout = "0x2222222222222222222222222222222222222AbC"

func payoutChallenge(signer string, oldRequired bool, oldAddr string, mutate func(string) string) string {
	nonce := strings.Repeat("b", 64)
	msg := BuildPayoutWalletMessage(testUUID, signer, newPayout, "base", nonce)
	if mutate != nil {
		msg = mutate(msg)
	}
	m := map[string]any{"nonce": nonce, "message": msg, "expiresAt": "t", "signer": signer, "oldWalletSignatureRequired": oldRequired, "oldWalletAddress": nil}
	if oldAddr != "" {
		m["oldWalletAddress"] = oldAddr
	}
	b, _ := json.Marshal(m)
	return string(b)
}

func TestPayoutWalletFirstSet(t *testing.T) {
	c, rt := newTestClient(t)
	s := &fakeSigner{addr: testAddr}
	rt.push(ok(payoutChallenge(testAddr, false, "", nil)),
		ok(`{"payoutWallet":{"address":"x","chain":"base","status":"active","activeFrom":"t"},"changed":true,"cooldownHours":72}`))
	r, err := c.PayoutWallet.Set(context.Background(), SetPayoutWalletOptions{Address: newPayout, Signer: s})
	if err != nil || !r.Changed || r.CooldownHours != 72 {
		t.Fatalf("%+v %v", r, err)
	}
	jsonEq(t, rt.reqs[0].Body, `{"address":"`+strings.ToLower(newPayout)+`","chain":"base"}`)
	if rt.reqs[1].Method != "PUT" || rt.reqs[1].Path != "/v1/payout-wallet" {
		t.Fatal("PUT")
	}
	jsonEq(t, rt.reqs[1].Body, `{"address":"`+strings.ToLower(newPayout)+`","chain":"base","nonce":"`+strings.Repeat("b", 64)+`","signature":"`+testSig+`"}`)
}

func TestPayoutWalletChangeOldSignerSignsSameMessage(t *testing.T) {
	c, rt := newTestClient(t)
	oldAddr := "0x3333333333333333333333333333333333333333"
	s := &fakeSigner{addr: testAddr}
	old := &fakeSigner{addr: oldAddr, sig: "0x" + strings.Repeat("cd", 65)}
	rt.push(ok(payoutChallenge(testAddr, true, oldAddr, nil)), ok(`{"changed":true}`))
	if _, err := c.PayoutWallet.Set(context.Background(), SetPayoutWalletOptions{Address: newPayout, Signer: s, OldWalletSigner: old}); err != nil {
		t.Fatal(err)
	}
	if len(old.calls) != 1 || len(s.calls) != 1 || old.calls[0] != s.calls[0] {
		t.Fatal("old signer must sign the same message")
	}
	if !strings.Contains(rt.reqs[1].Body, `"oldWalletSignature":"0x`+strings.Repeat("cd", 65)) {
		t.Fatal(rt.reqs[1].Body)
	}
}

func TestPayoutWalletRefusals(t *testing.T) {
	oldAddr := "0x3333333333333333333333333333333333333333"
	cases := map[string]struct {
		chal  string
		old   *fakeSigner
		check func(error) bool
	}{
		"mismatch":       {payoutChallenge(testAddr, false, "", func(m string) string { return strings.Replace(m, "Chain: base", "Chain: eth", 1) }), nil, isType[*ProtocolError]},
		"server signer":  {payoutChallenge("0x"+strings.Repeat("4", 40), false, "", nil), nil, isType[*ProtocolError]},
		"old missing":    {payoutChallenge(testAddr, true, oldAddr, nil), nil, isType[*ValidationError]},
		"old wrong addr": {payoutChallenge(testAddr, true, oldAddr, nil), &fakeSigner{addr: "0x" + strings.Repeat("5", 40)}, isType[*ValidationError]},
	}
	for name, tc := range cases {
		t.Run(name, func(t *testing.T) {
			c, rt := newTestClient(t)
			s := &fakeSigner{addr: testAddr}
			rt.push(ok(tc.chal))
			o := SetPayoutWalletOptions{Address: newPayout, Signer: s}
			if tc.old != nil {
				o.OldWalletSigner = tc.old
			}
			_, err := c.PayoutWallet.Set(context.Background(), o)
			if !tc.check(err) || len(s.calls) != 0 || len(rt.reqs) != 1 {
				t.Fatalf("err=%v calls=%d", err, len(s.calls))
			}
			if tc.old != nil && len(tc.old.calls) != 0 {
				t.Fatal("old signer called")
			}
		})
	}
}

// ---- wallet sign-in

func TestWalletSignIn(t *testing.T) {
	c, rt := bareClient(t)
	s := &fakeSigner{addr: testAddr}
	rt.push(ok(`{"message":"Sign in as `+strings.ToLower(testAddr)+`","nonce":"n"}`),
		ok(`{"token":"`+accessJWT+`","refreshToken":"`+refreshJWT+`","user":{"id":"u"}}`))
	r, err := c.WalletAuth.SignIn(context.Background(), s)
	if err != nil || r.User.ID != "u" || !c.IsConnected() {
		t.Fatalf("%v %v", r, err)
	}
	jsonEq(t, rt.reqs[1].Body, `{"address":"`+testAddr+`","signature":"`+testSig+`"}`)

	c2, rt2 := bareClient(t)
	s2 := &fakeSigner{addr: testAddr}
	rt2.push(ok(`{"message":"Sign in as 0x` + strings.Repeat("1", 40) + `"}`))
	if _, err := c2.WalletAuth.SignIn(context.Background(), s2); !isType[*ProtocolError](err) || len(s2.calls) != 0 {
		t.Fatalf("%v", err)
	}
}

func TestWalletVerifyMFAStoresNothing(t *testing.T) {
	c, rt := bareClient(t)
	rt.push(ok(`{"mfaRequired":true,"mfaChallengeToken":"mct","token":"` + accessJWT + `","refreshToken":"x"}`))
	r, err := c.WalletAuth.Verify(context.Background(), testAddr, testSig)
	if err != nil || !r.MfaRequired || r.MfaChallengeToken != "mct" || r.Token != "" || c.IsConnected() {
		t.Fatalf("%+v %v", r, err)
	}
}
